# --------------------------------------------------------------------------- #
# pass@k
# --------------------------------------------------------------------------- #


def _exact_pass_at_k(n: int, c: int, k: int) -> Fraction:
    """Reference implementation in exact rational arithmetic."""
    if k > n:
        raise ValueError("k > n")
    return Fraction(1) - Fraction(math.comb(n - c, k), math.comb(n, k))


@pytest.mark.parametrize(
    "n, c, k, expected",
    [
        (5, 2, 2, 0.7),  # 1 - C(3,2)/C(5,2) = 1 - 3/10
        (6, 2, 3, 0.8),  # 1 - C(4,3)/C(6,3) = 1 - 4/20
        (10, 1, 1, 0.1),
        (10, 1, 10, 1.0),
        (4, 0, 2, 0.0),
        (4, 4, 2, 1.0),
        (8, 3, 8, 1.0),
        (8, 3, 1, 0.375),
        (3, 1, 2, 2.0 / 3.0),  # 1 - C(2,2)/C(3,2) = 1 - 1/3
    ],
)
def test_pass_at_k_matches_hand_computed_values(n: int, c: int, k: int, expected: float) -> None:
    assert pass_at_k(n, c, k) == pytest.approx(expected, abs=1e-12)


def test_pass_at_k_is_not_the_naive_estimator() -> None:
    """The naive (c/n)**k form must not accidentally agree with the real one."""
    n, c, k = 8, 3, 4
    naive = 1.0 - (1.0 - c / n) ** k
    unbiased = pass_at_k(n, c, k)
    assert unbiased != pytest.approx(naive, abs=1e-6)
    # 1 - C(5,4)/C(8,4) = 1 - 5/70
    assert unbiased == pytest.approx(1.0 - 5.0 / 70.0, abs=1e-12)


def test_log_space_agrees_with_exact_fractions_for_small_n() -> None:
    checked = 0
    for n in range(1, 21):
        for c in range(0, n + 1):
            for k in range(1, n + 1):
                got = pass_at_k(n, c, k)
                want = float(_exact_pass_at_k(n, c, k))
                assert got == pytest.approx(want, abs=1e-12), (n, c, k, got, want)
                checked += 1
    assert checked > 1000


def test_log_comb_matches_math_comb() -> None:
    for n in range(0, 30):
        for k in range(0, n + 1):
            assert math.exp(log_comb(n, k)) == pytest.approx(float(math.comb(n, k)), rel=1e-9)
    assert log_comb(5, 6) == -math.inf
    assert log_comb(5, -1) == -math.inf


def test_pass_at_k_monotone_in_c_and_in_k() -> None:
    n = 12
    for k in (1, 3, 7, 12):
        values = [pass_at_k(n, c, k) for c in range(n + 1)]
        assert values == sorted(values)
        assert all(b >= a for a, b in zip(values, values[1:]))
    for c in (0, 1, 5, 11, 12):
        values = [pass_at_k(n, c, k) for k in range(1, n + 1)]
        assert all(b >= a for a, b in zip(values, values[1:]))


def test_pass_at_1_equals_c_over_n() -> None:
    assert pass_at_1(8, 3) == pytest.approx(0.375)
    assert pass_at_1(8, 3) == pytest.approx(pass_at_k(8, 3, 1))


def test_k_greater_than_n_raises_unless_clamped() -> None:
    with pytest.raises(ValueError, match="not estimable"):
        pass_at_k(4, 2, 8)
    assert pass_at_k(4, 2, 8, clamp_k=True) == pytest.approx(pass_at_k(4, 2, 4))


def test_degenerate_inputs_raise() -> None:
    with pytest.raises(ValueError):
        pass_at_k(0, 0, 1)
    with pytest.raises(ValueError):
        pass_at_k(5, 6, 1)
    with pytest.raises(ValueError):
        pass_at_k(5, -1, 1)
    with pytest.raises(ValueError):
        pass_at_k(5, 1, -1)


