def test_wilson_interval_known_value_and_containment() -> None:
    lo, hi = wilson_interval(3, 8, 0.95)
    # Hand-computed: z=1.959964, centre=(3+1.9208)/11.8416, half-width as in the source.
    assert lo == pytest.approx(0.1367, abs=5e-4)
    assert hi == pytest.approx(0.6938, abs=5e-4)
    assert lo < 3 / 8 < hi


def test_wilson_interval_is_never_degenerate_at_the_extremes() -> None:
    lo, hi = wilson_interval(0, 8)
    assert lo == pytest.approx(0.0, abs=1e-12)
    assert hi > 0.2, "0/8 must not be reported as a point estimate of exactly zero"
    lo, hi = wilson_interval(8, 8)
    assert hi == pytest.approx(1.0, abs=1e-12)
    assert lo < 0.8


def test_wilson_interval_narrows_with_n() -> None:
    widths = []
    for n in (8, 32, 128, 512):
        lo, hi = wilson_interval(n // 2, n)
        widths.append(hi - lo)
    assert widths == sorted(widths, reverse=True)


def test_jeffreys_interval_brackets_the_point_and_pins_the_endpoints() -> None:
    scipy = pytest.importorskip("scipy.stats")
    assert scipy is not None
    lo, hi = jeffreys_interval(3, 8)
    assert 0.0 < lo < 3 / 8 < hi < 1.0
    assert jeffreys_interval(0, 8)[0] == 0.0
    assert jeffreys_interval(8, 8)[1] == 1.0


def test_estimate_records_the_clamp_note() -> None:
    est = estimate(4, 2, 8)
    assert isinstance(est, PassKEstimate)
    assert est.effective_k == 4
    assert any("exceeds n=4" in note for note in est.notes)
    payload = est.as_dict()
    assert payload["k"] == 8 and payload["effective_k"] == 4
    assert payload["ci_method"] == "wilson"


def test_estimate_ci_contains_point_estimate() -> None:
    est = estimate(8, 3, 8)
    assert est.ci_low <= est.pass_at_1 <= est.ci_high
    assert est.pass_at_k >= est.pass_at_1


def test_estimate_rejects_unknown_ci_method() -> None:
    with pytest.raises(ValueError, match="unknown interval method"):
        estimate(8, 3, 4, ci_method="bootstrap")  # type: ignore[arg-type]


