def test_route_returns_a_tuple_of_route_and_rationale() -> None:
    got = route(0.375, 0.9, 8)
    assert isinstance(got, tuple) and len(got) == 2
    assert got[0] in ROUTES
    assert got[1].strip()


def test_branch_escalate_when_pass_at_k_is_zero() -> None:
    decision = route_decision(0.0, 0.0, 8)
    assert decision.route == "escalate"
    assert "solvable" in decision.rationale
    assert decision.confident is True


def test_branch_escalate_beats_a_supplied_interval() -> None:
    # Even a wide interval cannot manufacture evidence of solvability.
    decision = route_decision(0.0, 0.0, 8, ci=(0.0, 0.32))
    assert decision.route == "escalate"


def test_branch_reject_when_saturated() -> None:
    decision = route_decision(0.98, 1.0, 8, ci=(0.94, 0.999))
    assert decision.route == "reject"
    assert decision.band == "saturated"
    assert "contamination" in decision.rationale
    assert decision.confident is True


def test_branch_gold_in_band() -> None:
    decision = route_decision(0.375, 0.95, 8, ci=(0.20, 0.60))
    assert decision.route == "gold"
    assert decision.band == "gold"
    assert decision.confident is True
    assert "maximum" in decision.rationale


def test_branch_frontier_when_hard_but_reachable() -> None:
    decision = route_decision(0.02, 0.15, 8, ci=(0.001, 0.08))
    assert decision.route == "frontier"
    assert decision.band == "frontier"
    assert decision.confident is True


def test_branch_thin_band_between_0_7_and_0_9_is_reject_and_says_why() -> None:
    """The band the proposal leaves implicit: resolved explicitly as reject."""
    decision = route_decision(0.80, 0.99, 8, ci=(0.72, 0.88))
    assert decision.route == "reject"
    assert decision.band == "thin"
    assert "implicit" in decision.rationale
    assert "no contamination is implied" in decision.rationale.lower()
    # And it is distinguishable from the saturated case.
    saturated = route_decision(0.98, 1.0, 8, ci=(0.94, 0.999))
    assert saturated.band == "saturated"
    assert decision.rationale != saturated.rationale


def test_boundary_straddle_at_gold_lower_edge_goes_frontier() -> None:
    # 2/8: Wilson 95% is about [0.071, 0.591]; the point estimate is gold but
    # the interval reaches into the frontier band.
    est = estimate(8, 2, 8)
    decision = route_decision(est.pass_at_1, est.pass_at_k, 8, ci=est.ci)
    assert decision.point_route == "gold"
    assert decision.route == "frontier"
    assert decision.confident is False
    assert "straddles" in decision.rationale
    assert "0.10" in decision.rationale


def test_boundary_straddle_at_gold_upper_edge_keeps_the_task() -> None:
    # 4/8: Wilson 95% is about [0.215, 0.785]; a mid-band point estimate must
    # not be discarded because of eight-sample noise.
    est = estimate(8, 4, 8)
    decision = route_decision(est.pass_at_1, est.pass_at_k, 8, ci=est.ci)
    assert decision.point_route == "gold"
    assert decision.endpoint_routes == ("gold", "reject")
    assert decision.route == "gold"
    assert decision.confident is False
    assert "never discards" in decision.rationale


def test_boundary_straddle_from_the_reject_side_is_not_a_discard() -> None:
    # Point estimate in the thin band, interval reaching down into gold.
    decision = route_decision(0.80, 0.99, 8, ci=(0.53, 0.94))
    assert decision.point_route == "reject"
    assert decision.route == "gold"
    assert decision.confident is False


def test_a_very_wide_interval_lands_on_the_most_conservative_route() -> None:
    decision = route_decision(0.50, 0.99, 8, ci=(0.05, 0.95))
    assert set(decision.endpoint_routes) == {"frontier", "reject"}
    assert decision.route == "frontier"
    assert decision.confident is False


def test_no_interval_means_not_confident() -> None:
    decision = route_decision(0.375, 0.95, 8)
    assert decision.route == "gold"
    assert decision.confident is False
    assert "point estimate alone" in decision.rationale


def test_conservatism_order_covers_every_route_exactly_once() -> None:
    assert set(CONSERVATISM_ORDER) == set(ROUTES)
    assert len(CONSERVATISM_ORDER) == len(ROUTES)


def test_router_rejects_inconsistent_and_out_of_range_inputs() -> None:
    with pytest.raises(ValueError, match="non-decreasing"):
        route_decision(0.8, 0.4, 8)
    with pytest.raises(ValueError):
        route_decision(1.5, 1.0, 8)
    with pytest.raises(ValueError):
        route_decision(0.4, 0.9, 0)
    with pytest.raises(ValueError, match="inverted"):
        route_decision(0.4, 0.9, 8, ci=(0.8, 0.2))


def test_custom_bands_shift_the_decision() -> None:
    strict = RouteBands(gold_lo=0.05, gold_hi=0.50, saturated_lo=0.90)
    assert route_decision(0.60, 0.99, 8, ci=(0.55, 0.65), bands=strict).route == "reject"
    assert route_decision(0.60, 0.99, 8, ci=(0.55, 0.65)).route == "gold"


def test_route_bands_validate_their_ordering() -> None:
    with pytest.raises(ValueError):
        RouteBands(gold_lo=0.8, gold_hi=0.2)


