def _forbid_network(monkeypatch: pytest.MonkeyPatch) -> None:
    """Make every socket operation explode, then run the code under test."""

    def _boom(*args: Any, **kwargs: Any) -> Any:
        raise AssertionError("network access attempted during offline calibration")

    monkeypatch.setattr(socket, "socket", _boom)
    monkeypatch.setattr(socket, "create_connection", _boom)
    monkeypatch.setattr(socket, "getaddrinfo", _boom)


def test_stub_model_satisfies_the_protocol() -> None:
    assert isinstance(StubModel(), TargetModel)


def test_stub_model_is_deterministic_across_instances_and_runs(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    _forbid_network(monkeypatch)
    a = StubModel(seed=1234).generate("prompt", 8, 0.8, task_id="mut-rowsum-a1b2")
    b = StubModel(seed=1234).generate("prompt", 8, 0.8, task_id="mut-rowsum-a1b2")
    assert a == b
    assert len(a) == 8
    again = StubModel(seed=1234).generate("prompt", 8, 0.8, task_id="mut-rowsum-a1b2")
    assert again == a


def test_stub_model_never_touches_the_network(monkeypatch: pytest.MonkeyPatch) -> None:
    _forbid_network(monkeypatch)
    completions = StubModel().generate("anything", 4, 0.7, task_id="t")
    assert len(completions) == 4
    assert all(
        (STUB_CORRECT_MARKER in c) ^ (STUB_INCORRECT_MARKER in c) for c in completions
    )


def test_stub_pass_probability_varies_by_task_and_seed() -> None:
    stub = StubModel(seed=7)
    probs = {stub.pass_probability(f"task-{i}") for i in range(50)}
    assert len(probs) == 50, "distinct task ids must not collide onto one probability"
    assert min(probs) < 0.3 and max(probs) > 0.7, "the bank must span routing bands"
    assert stub.pass_probability("task-0") != StubModel(seed=8).pass_probability("task-0")


def test_stub_pass_rate_tracks_its_own_probability() -> None:
    stub = StubModel(seed=99)
    for task_id in ("alpha", "beta", "gamma"):
        p = stub.pass_probability(task_id)
        completions = stub.generate("p", 400, 0.8, task_id=task_id)
        observed = sum(1 for c in completions if STUB_CORRECT_MARKER in c) / len(completions)
        assert observed == pytest.approx(p, abs=0.08)


def test_stub_temperature_changes_the_draws_not_the_rate() -> None:
    stub = StubModel(seed=5)
    hot = stub.generate("p", 16, 1.0, task_id="x")
    cold = stub.generate("p", 16, 0.1, task_id="x")
    assert hot != cold
    assert stub.pass_probability("x") == stub.pass_probability("x")


def test_stub_falls_back_to_the_embedded_task_id() -> None:
    prompt = models_mod.embed_task_id("mut-xyz", "fix this")
    assert models_mod.extract_task_id(prompt) == "mut-xyz"
    via_prompt = StubModel().generate(prompt, 6, 0.8)
    direct = StubModel().generate("fix this", 6, 0.8, task_id="mut-xyz")
    assert [STUB_CORRECT_MARKER in c for c in via_prompt] == [
        STUB_CORRECT_MARKER in c for c in direct
    ]


