def test_grade_completion_uses_the_stub_marker_when_no_verifier_is_given() -> None:
    assert grade_completion(f"x {STUB_CORRECT_MARKER} y").correct is True
    assert grade_completion(f"x {STUB_INCORRECT_MARKER} y").correct is False


def test_grade_completion_refuses_to_guess() -> None:
    with pytest.raises(ValueError, match="refuses to guess"):
        grade_completion("def f(): pass")


def test_grade_completion_accepts_one_and_two_argument_verifiers() -> None:
    one: Callable[[str], bool] = lambda completion: "good" in completion
    seen: list[Any] = []

    def two(completion: str, task: Any) -> bool:
        seen.append(task)
        return "good" in completion

    assert grade_completion("this is good", verify=one).correct is True
    assert grade_completion("this is bad", verify=one).correct is False
    assert grade_completion("this is good", verify=two, task="T").correct is True
    assert seen == ["T"]


def test_grade_completion_lets_a_broken_verifier_fail_loudly() -> None:
    def broken(completion: str) -> bool:
        raise RuntimeError("oracle harness exploded")

    with pytest.raises(RuntimeError, match="exploded"):
        grade_completion("x", verify=broken)


