def test_icc_is_a_logistic_curve_through_its_own_difficulty() -> None:
    assert float(icc(1.5, 0.3, 0.3)) == pytest.approx(0.5)
    grid = np.linspace(-4, 4, 50)
    curve = icc(1.2, 0.0, grid)
    assert np.all(np.diff(curve) > 0)
    assert curve[0] < 0.05 and curve[-1] > 0.95


def test_fit_2pl_recovers_known_parameters_from_synthetic_2pl_data() -> None:
    """The real test: generate from known (a, b), fit, assert recovery."""
    rng = np.random.default_rng(20260818)
    n_items, n_resp, trials = 14, 90, 8
    true_a = rng.uniform(0.7, 2.2, size=n_items)
    true_b = rng.uniform(-1.8, 1.8, size=n_items)
    true_theta = rng.normal(0.0, 1.0, size=n_resp)

    successes, n_trials = simulate_2pl(true_a, true_b, true_theta, trials=trials, seed=11)
    fit = fit_2pl(successes, n_trials, priors=Priors())

    assert fit.converged, fit.message
    assert fit.n_items == n_items and fit.n_respondents == n_resp
    assert fit.n_observations == n_items * n_resp

    b_err = np.abs(fit.b - true_b)
    a_err = np.abs(fit.a - true_a)
    assert float(np.corrcoef(fit.b, true_b)[0, 1]) > 0.97, "difficulty ordering not recovered"
    assert float(np.corrcoef(fit.a, true_a)[0, 1]) > 0.85, "discrimination ordering not recovered"
    assert float(np.corrcoef(fit.theta, true_theta)[0, 1]) > 0.95, "ability not recovered"
    assert float(b_err.mean()) < 0.20, f"mean |b - b_hat| = {b_err.mean():.3f}"
    assert float(a_err.mean()) < 0.35, f"mean |a - a_hat| = {a_err.mean():.3f}"

    # Ordering alone is not enough: a 2PL fit can rank items perfectly while
    # reporting the whole scale shrunk or stretched (MAP shrinks theta and the
    # optimiser inflates a to compensate). Pin the scale down too.
    b_slope = float(np.polyfit(true_b, fit.b, 1)[0])
    a_slope = float(np.polyfit(true_a, fit.a, 1)[0])
    assert 0.7 < b_slope < 1.3, f"difficulty scale is off: slope {b_slope:.3f}"
    assert 0.7 < a_slope < 1.3, f"discrimination scale is off: slope {a_slope:.3f}"
    assert float(fit.theta.std()) == pytest.approx(1.0, abs=1e-6)
    assert float(fit.theta.mean()) == pytest.approx(0.0, abs=1e-6)


def test_neg_log_posterior_gradient_matches_finite_differences() -> None:
    """A wrong gradient can still converge somewhere plausible; pin it down."""
    from crucible.calibrate.irt import neg_log_posterior

    rng = np.random.default_rng(3)
    n_items, n_resp = 3, 6
    successes, trials = simulate_2pl(
        [0.8, 1.6, 2.0], [-0.5, 0.0, 1.0], rng.normal(size=n_resp), trials=5, seed=3
    )
    # Make one cell missing so the masking path is exercised too.
    successes[0, 0] = 0.0
    trials[0, 0] = 0.0

    priors = Priors()
    x = rng.normal(scale=0.6, size=2 * n_items + n_resp)
    value, grad = neg_log_posterior(x, successes, trials, n_items, priors)
    assert np.isfinite(value)

    eps = 1e-6
    for i in range(x.size):
        step = np.zeros_like(x)
        step[i] = eps
        up, _ = neg_log_posterior(x + step, successes, trials, n_items, priors)
        down, _ = neg_log_posterior(x - step, successes, trials, n_items, priors)
        numeric = (up - down) / (2 * eps)
        assert numeric == pytest.approx(grad[i], abs=1e-4, rel=1e-4), f"coordinate {i}"


def test_discrimination_ranking_orders_by_separating_power() -> None:
    rng = np.random.default_rng(5)
    true_a = np.array([2.4, 1.5, 0.8, 0.35])
    true_b = np.array([0.0, 0.2, -0.3, 0.1])
    theta = rng.normal(size=140)
    successes, trials = simulate_2pl(true_a, true_b, theta, trials=8, seed=5)
    fit = fit_2pl(successes, trials, item_ids=["sharp", "good", "dull", "flat"])

    ranking = fit.discrimination_ranking()
    assert [s.item_id for s in ranking][0] == "sharp"
    assert [s.item_id for s in ranking][-1] == "flat"
    assert ranking[0].discrimination > ranking[-1].discrimination
    assert ranking[0].peak_information > ranking[-1].peak_information
    assert fit.item("sharp").peak_information == pytest.approx(
        fit.item("sharp").discrimination ** 2 / 4.0
    )


def test_item_response_curve_and_serialisation() -> None:
    successes, trials = simulate_2pl([1.0, 1.4], [0.0, 0.5], np.linspace(-2, 2, 40), trials=4, seed=1)
    fit = fit_2pl(successes, trials, item_ids=["a", "b"], respondent_ids=[f"m{i}" for i in range(40)])
    grid, curve = fit.item_response_curve("a")
    assert grid.shape == curve.shape
    assert np.all(np.diff(curve) > 0)
    payload = fit.as_dict()
    assert payload["n_items"] == 2 and payload["n_respondents"] == 40
    assert [item["item_id"] for item in payload["items"]] == [
        s.item_id for s in fit.discrimination_ranking()
    ]
    assert set(payload["ability"]) == {f"m{i}" for i in range(40)}
    with pytest.raises(KeyError):
        fit.item("nope")


def test_fit_2pl_treats_zero_trial_cells_as_missing_not_as_failures() -> None:
    successes = np.array([[4.0, 0.0], [3.0, 4.0], [4.0, 3.0]])
    trials = np.array([[4.0, 0.0], [4.0, 4.0], [4.0, 4.0]])
    fit = fit_2pl(successes, trials)
    assert fit.n_observations == 5
    assert fit.items()[1].n_trials == 8


def test_fit_2pl_rejects_impossible_input() -> None:
    with pytest.raises(ValueError, match="0 <= successes <= trials"):
        fit_2pl(np.array([[5.0]]), np.array([[4.0]]))
    with pytest.raises(ValueError, match="entirely missing"):
        fit_2pl(np.array([[0.0, 0.0]]), np.array([[0.0, 0.0]]))
    with pytest.raises(ValueError, match="same shape"):
        fit_2pl(np.zeros((2, 3)), np.ones((2, 2)))
    with pytest.raises(ValueError, match="2-D"):
        fit_2pl(np.zeros(3), 1)


def test_priors_validate_their_scales() -> None:
    with pytest.raises(ValueError, match="log_a_sd"):
        Priors(log_a_sd=0.0)


