def test_contamination_needs_saturation_and_a_recalled_looking_trace() -> None:
    signal = flag_contamination(
        "mut-a",
        1.0,
        {"mean_tokens": 1800, "backtracks": 0, "entropy": 0.11},
    )
    assert signal.flagged is True
    assert signal.assessed is True
    assert signal.score == pytest.approx(1.0)
    assert len(signal.signals) == 3


def test_contamination_not_flagged_when_pass_rate_is_not_saturated() -> None:
    signal = flag_contamination(
        "mut-b",
        0.5,
        {"mean_tokens": 4000, "backtracks": 0, "entropy": 0.01},
    )
    assert signal.flagged is False
    assert signal.assessed is True
    assert "saturation threshold" in signal.reason


def test_contamination_not_flagged_when_the_trace_looks_exploratory() -> None:
    signal = flag_contamination(
        "mut-c",
        1.0,
        {"mean_tokens": 90, "backtracks": 12, "entropy": 0.92},
    )
    assert signal.flagged is False
    assert signal.assessed is True
    assert signal.signals == ()


def test_contamination_is_unassessed_when_trace_statistics_are_missing() -> None:
    """Absent evidence is reported as absent, never as a clean bill of health."""
    signal = flag_contamination("mut-d", 1.0, {"mean_tokens": 5000})
    assert signal.assessed is False
    assert signal.flagged is False
    assert "UNASSESSED" in signal.reason
    assert set(signal.missing_stats) == {"backtracks", "entropy"}

    none_at_all = flag_contamination("mut-e", 1.0, None)
    assert none_at_all.assessed is False and none_at_all.flagged is False


def test_contamination_accepts_alias_field_names_and_rejects_bad_input() -> None:
    signal = flag_contamination(
        "mut-f", 0.99, {"token_count": 900, "entropy_proxy": 0.2, "mean_backtracks": 0.5}
    )
    assert signal.assessed is True and signal.flagged is True
    with pytest.raises(ValueError):
        flag_contamination("mut-g", 1.4, {})


def test_contamination_thresholds_are_policy_inputs() -> None:
    stats = {"mean_tokens": 700, "backtracks": 0.5, "entropy": 0.5}
    lenient = flag_contamination("mut-h", 1.0, stats)
    strict = flag_contamination(
        "mut-h", 1.0, stats, ContaminationThresholds(min_signals=3, max_entropy=0.6)
    )
    assert lenient.flagged is True
    assert strict.flagged is True
    harsher = flag_contamination("mut-h", 1.0, stats, ContaminationThresholds(min_mean_tokens=5000))
    assert harsher.flagged is False


