def _write_bank(tmp_path: Path, make_task: Callable[..., Any], n: int = 6) -> Path:
    bank = tmp_path / "bank"
    bank.mkdir()
    for i in range(n):
        task = make_task(task_id=f"mut-synthetic-{i:03d}", calibration=None)
        task.save(bank / f"{task.task_id}.yaml")
    return bank


def test_calibrate_bank_runs_offline_end_to_end(
    tmp_path: Path, make_task: Callable[..., Any], cfg: Any, monkeypatch: pytest.MonkeyPatch
) -> None:
    bank = _write_bank(tmp_path, make_task, n=6)
    _forbid_network(monkeypatch)

    report = calibrate_bank(bank_dir=bank, model="stub", k=8, cfg=cfg)

    assert report.offline is True
    assert report.model == "stub"
    assert len(report.results) == 6
    assert report.errors == ()
    assert sum(report.route_counts.values()) == 6
    for item in report.results:
        assert item.decision.route in ROUTES
        assert item.estimate.n_samples == cfg.calibration_samples
        assert 0 <= item.estimate.n_correct <= item.estimate.n_samples
        assert item.decision.rationale.strip()
        # The driver measures only a whitespace token count; backtracks and
        # entropy cannot be recovered from a finished completion, so a
        # saturated task must come back UNASSESSED rather than clean.
        assert item.contamination.flagged is False
        assert set(item.contamination.missing_stats) == {"backtracks", "entropy"}
        assert item.contamination.assessed is (item.estimate.pass_at_1 < 0.95)


def test_calibrate_bank_is_deterministic(
    tmp_path: Path, make_task: Callable[..., Any], cfg: Any
) -> None:
    bank = _write_bank(tmp_path, make_task, n=4)
    first = calibrate_bank(bank_dir=bank, model="stub", k=8, cfg=cfg)
    second = calibrate_bank(bank_dir=bank, model="stub", k=8, cfg=cfg)
    assert [r.estimate.n_correct for r in first.results] == [
        r.estimate.n_correct for r in second.results
    ]
    assert [r.decision.route for r in first.results] == [r.decision.route for r in second.results]


def test_calibrate_bank_payload_is_json_shaped_for_the_cli(
    tmp_path: Path, make_task: Callable[..., Any], cfg: Any
) -> None:
    import json

    bank = _write_bank(tmp_path, make_task, n=3)
    report = calibrate_bank(bank_dir=bank, model="stub", k=8, cfg=cfg)
    payload = report.as_dict()
    json.dumps(payload)  # must not raise
    assert payload["n_tasks"] == 3
    assert set(payload["route_counts"]) == set(ROUTES)
    assert payload["tasks"][0]["estimate"]["ci_method"] == "wilson"


def test_calibrate_bank_accepts_caller_trace_stats_and_can_flag_contamination(
    tmp_path: Path, make_task: Callable[..., Any], cfg: Any
) -> None:
    bank = _write_bank(tmp_path, make_task, n=4)
    ids = [p.stem for p in sorted(bank.iterdir())]
    supplied = {tid: {"backtracks": 0, "entropy": 0.05, "mean_tokens": 2000} for tid in ids}
    report = calibrate_bank(bank_dir=bank, model="stub", k=8, cfg=cfg, trace_stats=supplied)
    assert all(item.contamination.assessed for item in report.results)
    for item in report.results:
        expected = item.estimate.pass_at_1 >= 0.95
        assert item.contamination.flagged is expected


def test_calibrate_bank_uses_a_supplied_verifier(
    tmp_path: Path, make_task: Callable[..., Any], cfg: Any
) -> None:
    bank = _write_bank(tmp_path, make_task, n=3)
    calls: list[str] = []

    def always_wrong(completion: str, task: Any) -> bool:
        calls.append(getattr(task, "task_id", "?"))
        return False

    report = calibrate_bank(bank_dir=bank, model="stub", k=8, cfg=cfg, verify=always_wrong)
    assert len(calls) == 3 * cfg.calibration_samples
    assert all(item.estimate.n_correct == 0 for item in report.results)
    assert all(item.decision.route == "escalate" for item in report.results)


def test_calibrate_bank_writes_back_only_when_asked(
    tmp_path: Path, make_task: Callable[..., Any], cfg: Any
) -> None:
    from crucible.schema import Task

    bank = _write_bank(tmp_path, make_task, n=2)
    calibrate_bank(bank_dir=bank, model="stub", k=8, cfg=cfg)
    assert all(Task.load(p).calibration is None for p in sorted(bank.iterdir()))

    calibrate_bank(bank_dir=bank, model="stub", k=8, cfg=cfg, write_back=True)
    for p in sorted(bank.iterdir()):
        record = Task.load(p).calibration
        assert record is not None
        assert record.model == "stub"
        assert record.route in ROUTES
        assert record.rationale.strip()


def test_calibrate_bank_reports_unreadable_files_instead_of_aborting(
    tmp_path: Path, make_task: Callable[..., Any], cfg: Any
) -> None:
    bank = _write_bank(tmp_path, make_task, n=2)
    (bank / "broken.yaml").write_text("this: [is not a task", encoding="utf-8")
    report = calibrate_bank(bank_dir=bank, model="stub", k=8, cfg=cfg)
    assert len(report.results) == 2
    assert len(report.errors) == 1
    assert "broken.yaml" in report.errors[0]["path"]


def test_calibrate_bank_rejects_a_missing_directory(tmp_path: Path, cfg: Any) -> None:
    from crucible.errors import CrucibleError

    with pytest.raises(CrucibleError, match="bank directory not found"):
        calibrate_bank(bank_dir=tmp_path / "nope", model="stub", k=8, cfg=cfg)


def test_calibration_record_round_trips_through_the_schema(
    tmp_path: Path, make_task: Callable[..., Any], cfg: Any
) -> None:
    from crucible.schema import Task

    bank = _write_bank(tmp_path, make_task, n=1)
    calibrate_bank(bank_dir=bank, model="stub", k=8, cfg=cfg, write_back=True)
    path = next(iter(sorted(bank.iterdir())))
    reloaded = Task.from_yaml(Task.load(path).to_yaml())
    assert reloaded.calibration is not None
    assert reloaded.calibration.k <= 8


